// AI CHAT INTEGRATION
(function() {
  const aiWidget = document.getElementById('ai-assistant-widget');
  const aiFloatingBtn = document.getElementById('ai-floating-btn');
  const aiCloseBtn = document.getElementById('ai-close-btn');
  const aiForm = document.getElementById('ai-form');
  const aiInput = document.getElementById('ai-input');
  const aiMessages = document.getElementById('ai-messages');
  let currentConversationId = null;

  if (aiFloatingBtn && aiWidget && aiCloseBtn) {
    aiFloatingBtn.addEventListener('click', () => {
      aiWidget.classList.remove('hidden');
      aiFloatingBtn.classList.add('hidden');
    });

    aiCloseBtn.addEventListener('click', () => {
      aiWidget.classList.add('hidden');
      aiFloatingBtn.classList.remove('hidden');
    });
  }

  function addMessage(role, content) {
    if (!aiMessages) return;
    const div = document.createElement('div');
    div.className = 'ai-message ' + (role === 'user' ? 'ai-message-user' : 'ai-message-assistant');
    div.textContent = content;
    aiMessages.appendChild(div);
    aiMessages.scrollTop = aiMessages.scrollHeight;
  }

  if (aiForm) {
    aiForm.addEventListener('submit', async (e) => {
      e.preventDefault();
      const msg = aiInput.value.trim();
      if (!msg) return;

      addMessage('user', msg);
      aiInput.value = '';
      
      const token = localStorage.getItem('parcelpilot_token');
      if (!token) {
        addMessage('assistant', 'Please log in to use the support assistant.');
        return;
      }

      const payload = { message: msg };
      if (currentConversationId) {
        payload.conversation_id = currentConversationId;
      }

      try {
        const btn = document.getElementById('ai-send-btn');
        btn.disabled = true;
        btn.textContent = '...';

        const res = await fetch('/api/v1/chat', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + token
          },
          body: JSON.stringify(payload)
        });

        if (!res.ok) {
          const err = await res.json();
          addMessage('assistant', 'Error: ' + (err.detail || 'Failed to send message'));
        } else {
          const data = await res.json();
          currentConversationId = data.conversation_id;
          addMessage('assistant', data.response);
        }
      } catch (err) {
        addMessage('assistant', 'Connection error. Please try again.');
      } finally {
        const btn = document.getElementById('ai-send-btn');
        btn.disabled = false;
        btn.textContent = 'Send';
      }
    });
  }
})();

